/usr/bin/bash -lc "sed -n '280,380p' tests/middleware/test_base.py; sed -n '1,45p' tests/middleware/test_base.py; python - <<'PY'
import traceback

stored = None
try:
    try:
        raise LookupError('cause')
    except LookupError:
        raise RuntimeError('app')
except Exception as exc:
    stored = exc

try:
    raise EOFError('stream')
except EOFError:
    old_style = stored
    try:
        raise old_style
    except Exception as exc:
        print('inside:', type(exc.__context__).__name__, type(exc.__context__.__context__).__name__)

stored = None
try:
    try:
        raise LookupError('cause')
    except LookupError:
        raise RuntimeError('app')
except Exception as exc:
    stored = exc

try:
    raise EOFError('stream')
except EOFError:
    pass
try:
    raise stored
except Exception as exc:
    print('outside:', type(exc.__context__).__name__, exc.__context__.__context__)
PY"

